
'use strict';
// Exercise configuration only; the camera, scope and acquisition remain shared.
let activeExercise='one';
function exerciseStatus(text,error=false){$('exerciseStatus').textContent=text;$('exerciseStatus').classList.toggle('error',error);}
function setExerciseDataName(exercise){$('session').value=exercise==='three'?'spatial-rf':'orientation-tuning';}
function applyExercise(exercise){if(exercise==='four'){if(recording){$('exerciseSelect').value=activeExercise;message('Stop recording before changing exercise.',true);return;}location.href='./mystery-neuron.html';return;}if(recording){$('exerciseSelect').value=activeExercise;message('Stop recording before changing exercise.',true);return;}if(pausedScope)$('pauseViewing').click();if((activeExercise==='two'||activeExercise==='three')&&exercise!==activeExercise)leaveExerciseTwo();if(['one','two','three'].includes(exercise)){dockMonitor();$('dockCamera').click();}activeExercise=exercise;$('exerciseSelect').value=exercise;document.body.dataset.exercise=exercise;send('stop');
  if(exercise==='one'){cameraRFModel={...modelDisplay.model,...exerciseOneModel()};if(compiling)cancelCompile();scope.setFilter({highpass:300,lowpass:6000});scope.setThreshold(-70);$('threshold').value=-70;$('filterPreset').value='spikes';$('highpass').value=300;$('lowpass').value=6000;$('reveal').checked=false;$('showCameraRF').checked=false;drawRF();$('inputSource').value='webcam';$('cameraMirror').checked=true;$('cameraMirror').dispatchEvent(new Event('change'));$('cameraStatus').textContent='Start the webcam. Hold paper, bars or gratings in front of it and watch/listen for spikes.';exerciseStatus('Goal: figure out what makes this neuron fire.');}
  else if(exercise==='two'){if(compiling)cancelCompile();loadProtocolForExercise('two');setExerciseDataName('two');$('gratingSize').value=140;updateControls();$('reveal').checked=false;drawRF();$('inputSource').value='webcam';$('cameraMirror').checked=false;$('cameraMirror').dispatchEvent(new Event('change'));enterExerciseTwo();}
  else if(exercise==='three'){if(compiling)cancelCompile();loadProtocolForExercise('three');setExerciseDataName('three');$('gratingSize').value=25;updateControls();$('reveal').checked=false;drawRF();$('inputSource').value='webcam';$('cameraMirror').checked=false;$('cameraMirror').dispatchEvent(new Event('change'));enterExerciseThree();}
  send('exerciseProfile',{exercise});window.refreshVisualInput?.();const hash=exercise==='one'?'#exercise-1':exercise==='two'?'#exercise-2':'#exercise-3';if(location.hash!==hash)history.replaceState(null,'',hash);
}
$('exerciseSelect').onchange=()=>applyExercise($('exerciseSelect').value);function exerciseFromHash(){if(location.hash==='#exercise-4')return 'four';return location.hash==='#exercise-3'?'three':location.hash==='#exercise-2'?'two':'one';}window.addEventListener('hashchange',()=>{const next=exerciseFromHash();if(next!==activeExercise)applyExercise(next);});applyExercise(exerciseFromHash());
